/**
 * Relations for Drizzle's relational query API (`db.query.*`). Generated by `drizzle-kit pull`
 * from the legacy foreign keys, then renamed for readability (e.g. `homeTeam` / `awayTeam`).
 */
import { relations } from 'drizzle-orm';
import {
	articleComments,
	articles,
	clubs,
	competitions,
	deleteRequests,
	gameComments,
	gameGroups,
	gameReferees,
	games,
	goals,
	groupRules,
	groupRulesPositions,
	media,
	mvpVotes,
	permissions,
	playerUpdateRequests,
	players,
	playgrounds,
	pollAnswerVotes,
	pollAnswers,
	polls,
	refereeTypes,
	referees,
	seasons,
	teamAgents,
	teamAgentsHistory,
	teams,
	transfers,
	userBans,
	userPermissions,
	userProfiles,
	userUuids,
	users
} from './schema';

export const articleCommentsRelations = relations(articleComments, ({ one, many }) => ({
	parent: one(articleComments, {
		fields: [articleComments.articleCommentId],
		references: [articleComments.id],
		relationName: 'articleCommentReplies'
	}),
	replies: many(articleComments, { relationName: 'articleCommentReplies' }),
	article: one(articles, { fields: [articleComments.articleId], references: [articles.id] }),
	user: one(users, { fields: [articleComments.userId], references: [users.id] })
}));

export const articlesRelations = relations(articles, ({ one, many }) => ({
	comments: many(articleComments),
	media: one(media, { fields: [articles.mediaId], references: [media.id] }),
	user: one(users, { fields: [articles.userId], references: [users.id] })
}));

export const usersRelations = relations(users, ({ one, many }) => ({
	profile: one(userProfiles),
	articleComments: many(articleComments),
	articles: many(articles),
	administeredClubs: many(clubs),
	deleteRequests: many(deleteRequests),
	gameComments: many(gameComments),
	media: many(media),
	mvpVotes: many(mvpVotes),
	reviewedPlayerUpdateRequests: many(playerUpdateRequests),
	pollAnswerVotes: many(pollAnswerVotes),
	bans: many(userBans, { relationName: 'bannedUser' }),
	bansIssued: many(userBans, { relationName: 'bannedBy' }),
	userPermissions: many(userPermissions),
	uuids: many(userUuids)
}));

export const mediaRelations = relations(media, ({ one, many }) => ({
	articles: many(articles),
	user: one(users, { fields: [media.userId], references: [users.id] })
}));

export const clubsRelations = relations(clubs, ({ one, many }) => ({
	adminUser: one(users, { fields: [clubs.adminUserId], references: [users.id] }),
	playgrounds: many(playgrounds),
	teams: many(teams)
}));

export const deleteRequestsRelations = relations(deleteRequests, ({ one }) => ({
	user: one(users, { fields: [deleteRequests.userId], references: [users.id] })
}));

export const gameCommentsRelations = relations(gameComments, ({ one }) => ({
	game: one(games, { fields: [gameComments.gameId], references: [games.id] }),
	team: one(teams, { fields: [gameComments.teamId], references: [teams.id] }),
	user: one(users, { fields: [gameComments.userId], references: [users.id] })
}));

export const gamesRelations = relations(games, ({ one, many }) => ({
	gameComments: many(gameComments),
	gameReferees: many(gameReferees),
	homeTeam: one(teams, {
		fields: [games.homeTeamId],
		references: [teams.id],
		relationName: 'homeTeam'
	}),
	awayTeam: one(teams, {
		fields: [games.awayTeamId],
		references: [teams.id],
		relationName: 'awayTeam'
	}),
	gameGroup: one(gameGroups, { fields: [games.gameGroupId], references: [gameGroups.id] }),
	playground: one(playgrounds, { fields: [games.playgroundId], references: [playgrounds.id] }),
	goals: many(goals),
	mvpVotes: many(mvpVotes)
}));

export const teamsRelations = relations(teams, ({ one, many }) => ({
	gameComments: many(gameComments),
	homeGames: many(games, { relationName: 'homeTeam' }),
	awayGames: many(games, { relationName: 'awayTeam' }),
	goals: many(goals),
	players: many(players),
	teamAgents: many(teamAgents),
	club: one(clubs, { fields: [teams.clubId], references: [clubs.id] }),
	transfers: many(transfers)
}));

export const gameGroupsRelations = relations(gameGroups, ({ one, many }) => ({
	groupRules: one(groupRules, {
		fields: [gameGroups.groupRulesId],
		references: [groupRules.id]
	}),
	season: one(seasons, { fields: [gameGroups.seasonId], references: [seasons.id] }),
	games: many(games)
}));

export const groupRulesRelations = relations(groupRules, ({ many }) => ({
	gameGroups: many(gameGroups),
	positions: many(groupRulesPositions)
}));

export const seasonsRelations = relations(seasons, ({ one, many }) => ({
	gameGroups: many(gameGroups),
	competition: one(competitions, {
		fields: [seasons.competitionId],
		references: [competitions.id]
	})
}));

export const gameRefereesRelations = relations(gameReferees, ({ one }) => ({
	game: one(games, { fields: [gameReferees.gameId], references: [games.id] }),
	referee: one(referees, { fields: [gameReferees.refereeId], references: [referees.id] }),
	refereeType: one(refereeTypes, {
		fields: [gameReferees.refereeTypeId],
		references: [refereeTypes.id]
	})
}));

export const refereesRelations = relations(referees, ({ many }) => ({
	gameReferees: many(gameReferees)
}));

export const refereeTypesRelations = relations(refereeTypes, ({ many }) => ({
	gameReferees: many(gameReferees)
}));

export const playgroundsRelations = relations(playgrounds, ({ one, many }) => ({
	games: many(games),
	club: one(clubs, { fields: [playgrounds.clubId], references: [clubs.id] })
}));

export const goalsRelations = relations(goals, ({ one }) => ({
	game: one(games, { fields: [goals.gameId], references: [games.id] }),
	player: one(players, { fields: [goals.playerId], references: [players.id] }),
	team: one(teams, { fields: [goals.teamId], references: [teams.id] })
}));

export const playersRelations = relations(players, ({ one, many }) => ({
	goals: many(goals),
	mvpVotes: many(mvpVotes),
	updateRequests: many(playerUpdateRequests),
	team: one(teams, { fields: [players.teamId], references: [teams.id] }),
	teamAgents: many(teamAgents),
	transfers: many(transfers)
}));

export const groupRulesPositionsRelations = relations(groupRulesPositions, ({ one }) => ({
	groupRules: one(groupRules, {
		fields: [groupRulesPositions.groupRulesId],
		references: [groupRules.id]
	})
}));

export const mvpVotesRelations = relations(mvpVotes, ({ one }) => ({
	game: one(games, { fields: [mvpVotes.gameId], references: [games.id] }),
	player: one(players, { fields: [mvpVotes.playerId], references: [players.id] }),
	user: one(users, { fields: [mvpVotes.userId], references: [users.id] })
}));

export const playerUpdateRequestsRelations = relations(playerUpdateRequests, ({ one }) => ({
	player: one(players, { fields: [playerUpdateRequests.playerId], references: [players.id] }),
	reviewer: one(users, { fields: [playerUpdateRequests.reviewedBy], references: [users.id] })
}));

export const pollAnswerVotesRelations = relations(pollAnswerVotes, ({ one }) => ({
	pollAnswer: one(pollAnswers, {
		fields: [pollAnswerVotes.pollAnswerId],
		references: [pollAnswers.id]
	}),
	user: one(users, { fields: [pollAnswerVotes.userId], references: [users.id] })
}));

export const pollAnswersRelations = relations(pollAnswers, ({ one, many }) => ({
	votes: many(pollAnswerVotes),
	poll: one(polls, { fields: [pollAnswers.pollId], references: [polls.id] })
}));

export const pollsRelations = relations(polls, ({ many }) => ({
	answers: many(pollAnswers)
}));

export const competitionsRelations = relations(competitions, ({ many }) => ({
	seasons: many(seasons)
}));

export const teamAgentsRelations = relations(teamAgents, ({ one, many }) => ({
	player: one(players, { fields: [teamAgents.playerId], references: [players.id] }),
	team: one(teams, { fields: [teamAgents.teamId], references: [teams.id] }),
	history: many(teamAgentsHistory)
}));

export const teamAgentsHistoryRelations = relations(teamAgentsHistory, ({ one }) => ({
	teamAgent: one(teamAgents, {
		fields: [teamAgentsHistory.teamAgentId],
		references: [teamAgents.id]
	})
}));

export const transfersRelations = relations(transfers, ({ one }) => ({
	player: one(players, { fields: [transfers.playerId], references: [players.id] }),
	team: one(teams, { fields: [transfers.teamId], references: [teams.id] })
}));

export const userBansRelations = relations(userBans, ({ one }) => ({
	bannedBy: one(users, {
		fields: [userBans.bannedByUserId],
		references: [users.id],
		relationName: 'bannedBy'
	}),
	bannedUser: one(users, {
		fields: [userBans.bannedUserId],
		references: [users.id],
		relationName: 'bannedUser'
	})
}));

export const userPermissionsRelations = relations(userPermissions, ({ one }) => ({
	permission: one(permissions, {
		fields: [userPermissions.permissionId],
		references: [permissions.id]
	}),
	user: one(users, { fields: [userPermissions.userId], references: [users.id] })
}));

export const permissionsRelations = relations(permissions, ({ many }) => ({
	userPermissions: many(userPermissions)
}));

export const userProfilesRelations = relations(userProfiles, ({ one }) => ({
	user: one(users, { fields: [userProfiles.userId], references: [users.id] })
}));

export const userUuidsRelations = relations(userUuids, ({ one }) => ({
	user: one(users, { fields: [userUuids.userId], references: [users.id] })
}));
